from taf.config.testline import Airscale, CommonUnit  # noqa: F401
from taf.config.testline.info.endpoints.hardware_endpoints import HardwareEndpoints
from taf.config.testline.info.endpoints.hardware_helper import SupportedHwTypes


class AirscaleEndpoints(object):
    def __init__(self, airscale):
        # type: (Airscale) -> None
        self.airscale = airscale

    def get_airscale_endpoint(self):
        # type: () -> HardwareEndpoints
        return HardwareEndpoints(self._get_endpoints(self.airscale.common_units))

    def _get_endpoints(self, units):
        hardware = []
        for index, unit in enumerate(units):
            unit_endpoint = self._get_specific_hw_type(unit.hardware_type)
            if isinstance(unit, CommonUnit):
                hardware += [self._get_common_hw_recursive(unit_endpoint, index, unit)]
            else:
                hardware += [self._get_capacity_hw(unit_endpoint, index)]
        return hardware

    def _get_common_hw_recursive(self, unit_endpoint, index, unit):
        return unit_endpoint(index, self._get_endpoints(unit.capacity_units))

    def _get_capacity_hw(self, unit_endpoint, index):
        return unit_endpoint(index)

    def _get_specific_hw_type(self, hardware_type):
        return SupportedHwTypes.get_hw(hardware_type)
